package estate.svc;

import org.junit.jupiter.api.Test;

import java.sql.Statement;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class MainTest {
    private Main start(FakeContext c) throws Exception {
        Main m = new Main();
        m.start(c);
        return m;
    }

    @Test
    void postStoresAndPublishes() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        Map<String, String> r = m.handle("post", Map.of("account", "a1", "amount", "12.5", "requestId", "r1"));
        assertEquals("false", r.get("dup"));
        assertEquals("12.50", m.handle("balance", Map.of("account", "a1")).get("balance"));
        assertEquals("payment.posted", c.published.get(0));
        assertEquals("1250", c.events.get(0).get("amountMinor"));
        assertFalse(c.events.get(0).containsKey("amount"));
    }

    @Test
    void sameRequestIdPostsOnce() throws Exception {
        FakeContext c = new FakeContext();
        Main m = start(c);
        m.handle("post", Map.of("account", "a1", "amount", "5.00", "requestId", "r1"));
        Map<String, String> r = m.handle("post", Map.of("account", "a1", "amount", "5.00", "requestId", "r1"));
        assertEquals("true", r.get("dup"));
        assertEquals("1", m.handle("postings", Map.of("account", "a1")).get("count"));
        assertEquals(1, c.events.size());
    }

    @Test
    void healthIsUp() throws Exception {
        assertEquals("UP", start(new FakeContext()).handle("health", Map.of()).get("status"));
    }

    @Test
    void migratesExistingPostingsToMinorUnits() throws Exception {
        FakeContext c = new FakeContext();
        try (Statement s = c.db().createStatement()) {
            s.execute("CREATE TABLE schema_version(v INT NOT NULL)");
            s.execute("INSERT INTO schema_version(v) VALUES (1)");
            s.execute("CREATE TABLE postings(id BIGINT AUTO_INCREMENT PRIMARY KEY, account VARCHAR(40) NOT NULL, "
                    + "amount DECIMAL(18,2) NOT NULL, request_id VARCHAR(80) NOT NULL UNIQUE, ts BIGINT NOT NULL)");
            s.execute("INSERT INTO postings(account, amount, request_id, ts) VALUES ('a1', 12.25, 'old', 1)");
        }

        Main m = start(c);
        assertEquals("12.25", m.handle("balance", Map.of("account", "a1")).get("balance"));
        Map<String, String> r = m.handle("post", Map.of("account", "a1", "amount", "1.75", "requestId", "new"));
        assertEquals("175", c.events.get(0).get("amountMinor"));
        assertEquals("14.00", m.handle("balance", Map.of("account", "a1")).get("balance"));
        assertEquals("2", m.handle("postings", Map.of("account", "a1")).get("count"));
        assertEquals("false", r.get("dup"));
    }
}
